t=df['t'].values; P=df['P'].values; y=df['dP_dt'].values
def cands(w):
    s=np.sin(w*t); c=np.cos(w*t)
    d={'1':np.ones_like(P),'t':t,'P':P,'sqP':np.sqrt(P),'P2':P**2,'t2':t**2,'tP':t*P,'expt':np.exp(-t),
       'Ps':P*s,'Pc':P*c,'s':s,'c':c,'sqPs':np.sqrt(P)*s,'sqPc':np.sqrt(P)*c,'ts':t*s,'tc':t*c,'logP':np.log(P),'1/P':1/P,'t2P':t*t*P,'P3':P**3,'lnt':np.log(t),'sqt':np.sqrt(t),'Pexpt':P*np.exp(-t)}
    return d
def score(w, names):
    d=cands(w)
    X=np.c_[[d[n] for n in names]].T
    c=np.linalg.lstsq(X,y,rcond=None)[0]
    return np.mean((y-X@c)**2)/np.var(y)
